def _dedupe_symbol_tokens(raw_items) -> list[str]:
    cleaned: list[str] = []
    seen: set[str] = set()
    for raw in raw_items:
        symbol = str(raw or "").strip().upper()
        if not symbol or symbol in seen:
            continue
        seen.add(symbol)
        cleaned.append(symbol)
    return cleaned


